function productImageUrl_(path) {
  if (!path) return '';
  return requireSupabase_().storage.from(PRODUCT_IMAGE_BUCKET).getPublicUrl(path).data.publicUrl || '';
}

function findProductItem_(idOrName) {
  if (!idOrName) return null;
  const list = typeof products !== 'undefined' && Array.isArray(products) ? products : [];
  const allList = typeof allProducts !== 'undefined' && Array.isArray(allProducts) ? allProducts : [];
  return list.find((p) => p.id === idOrName || p.name === idOrName)
    || allList.find((p) => p.id === idOrName || p.name === idOrName)
    || null;
}

function renderProductThumbHtml_(imageUrl, productName = 'Product', iconColor = '#38bdf8') {
  return `
    <div class="product-thumb-frame" style="width:36px;height:36px;border-radius:8px;overflow:hidden;flex-shrink:0;background:#0d1b2a;border:1px solid rgba(56,189,248,0.25);display:grid;place-items:center;">
      ${imageUrl
        ? `<img class="product-photo-thumb" src="${escapeHtml(imageUrl)}" alt="${escapeHtml(productName)}" style="width:100%;height:100%;object-fit:cover;" loading="lazy" />`
        : `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" style="width:16px;height:16px;color:${iconColor};"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/><polyline points="3.29 7 12 12 20.71 7"/></svg>`}
    </div>
  `;
}

async function uploadProductImage_(file, productId) {
  if (!(file instanceof File) || file.size === 0) return '';
  if (!['image/jpeg', 'image/png', 'image/webp'].includes(file.type)) throw new Error('Use a JPG, PNG, or WebP product photo.');
  if (file.size > PRODUCT_IMAGE_MAX_BYTES) throw new Error('Product photo must be 2 MB or smaller.');
  const extension = file.type === 'image/png' ? 'png' : file.type === 'image/webp' ? 'webp' : 'jpg';
  const path = `${productId}/${crypto.randomUUID()}.${extension}`;
  const { error } = await requireSupabase_().storage.from(PRODUCT_IMAGE_BUCKET).upload(path, file, { contentType: file.type, upsert: false });
  throwIfError_(error);
  return path;
}

let badgeAlignmentFrame = 0;
function alignTableBadges() {
  const tables = document.querySelectorAll('#inventoryTable, .std-table-shell, .grid-table, dialog table, dialog .table-shell');
  if (!tables.length) return;

  const BADGE_SELECTOR = '.stock-pill, .low-stock-pill, .category-badge, .transfer-badge, .credit-sale-badge, .payment-collected-badge, .in-transit-badge, .bundle-pill, .individual-pill';
  const isMobile = window.matchMedia('(max-width: 640px)').matches;

  tables.forEach((table) => {
    const rows = table.querySelectorAll('.std-table-row:not(.std-table-header), .table-row:not(.table-header), tbody tr');
    if (!rows.length) return;

    // Phase 1: Reset all badge dimensions to measure natural unconstrained text width
    rows.forEach((row) => {
      row.querySelectorAll(BADGE_SELECTOR).forEach((badge) => {
        badge.style.width = '';
        badge.style.minWidth = '';
      });
    });

    if (isMobile) return;

    // Phase 2: Group badges by column (using cell data-label, data-col, or column index)
    const columns = new Map();

    rows.forEach((row) => {
      const cells = row.querySelectorAll('[data-label]');
      const cellList = cells.length ? Array.from(cells) : Array.from(row.children);

      cellList.forEach((cell, cellIdx) => {
        const badgesInCell = Array.from(cell.querySelectorAll(BADGE_SELECTOR));
        if (!badgesInCell.length) return;

        const baseKey = cell.getAttribute('data-label') || cell.getAttribute('data-col') || `col_${cellIdx}`;

        badgesInCell.forEach((badge, subIdx) => {
          const colKey = badgesInCell.length > 1 ? `${baseKey}__${subIdx}` : baseKey;

          let colData = columns.get(colKey);
          if (!colData) {
            colData = { maxWidth: 0, badges: [] };
            columns.set(colKey, colData);
          }

          const rect = badge.getBoundingClientRect();
          if (rect.width > 0) {
            const w = Math.ceil(Math.max(rect.width, badge.scrollWidth || 0, badge.offsetWidth || 0));
            if (w > colData.maxWidth) {
              colData.maxWidth = w;
            }
            colData.badges.push(badge);
          }
        });
      });
    });

    // Phase 3: Set all badges in each column to the uniform width of the longest text in that column
    columns.forEach((colData) => {
      if (colData.maxWidth > 0) {
        const px = `${colData.maxWidth}px`;
        colData.badges.forEach((badge) => {
          badge.style.width = px;
          badge.style.minWidth = px;
          badge.style.justifyContent = 'center';
          badge.style.textAlign = 'center';
        });
      }
    });
  });
}

function scheduleBadgeAlignment() {
  cancelAnimationFrame(badgeAlignmentFrame);
  badgeAlignmentFrame = requestAnimationFrame(alignTableBadges);
}

function escapeHtml(value) {
  return String(value ?? '').replace(/[&<>'"]/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' })[char]);
}

function displayCustomerName(value) {
  return String(value ?? '').toUpperCase();
}

function sortByName_(rows, key = 'name') {
  return [...rows].sort((left, right) => String(left[key] || '').localeCompare(String(right[key] || ''), 'en', { sensitivity: 'base' }));
}

function readBundleComponents_(formEl, productType) {
  if (productType !== 'bundle') return [];
  const rows = [...formEl.querySelectorAll('[data-bundle-component-row]')].map((row) => ({
    productId: row.querySelector('[name="bundleComponentProduct"]')?.value || '',
    qty: Number(row.querySelector('[name="bundleComponentQty"]')?.value || 0),
  }));
  if (!rows.length || rows.some((item) => !item.productId || !Number.isFinite(item.qty) || item.qty <= 0)) {
    throw new Error('Add at least one component and enter a quantity for each one.');
  }
  if (new Set(rows.map((item) => item.productId)).size !== rows.length) throw new Error('A component can only be added once to a bundle.');
  return rows;
}

function readTransferLines_(formEl) {
  const lines = [...formEl.querySelectorAll('[data-transfer-line]')].map((row) => ({
    productId: row.querySelector('[name="transferProduct"]')?.value || '',
    qty: Number(row.querySelector('[name="transferQty"]')?.value || 0),
  }));
  if (!lines.length || lines.some((line) => !line.productId || !Number.isFinite(line.qty) || line.qty <= 0)) throw new Error('Add at least one valid transfer line.');
  if (new Set(lines.map((line) => line.productId)).size !== lines.length) throw new Error('Add each product or bundle only once per transfer.');
  return lines;
}

function readStockInLines_(formEl) {
  const lines = [...formEl.querySelectorAll('[data-stock-in-line]')].map((row) => ({
    productId: row.querySelector('[name="productId"]')?.value || '', qty: Number(row.querySelector('[name="qty"]')?.value || 0),
    unitCost: Number(row.querySelector('[name="unitCost"]')?.value || 0), quarantineQty: Number(row.querySelector('[name="quarantineQty"]')?.value || 0), sellingPrice: Number(row.querySelector('[name="sellingPrice"]')?.value || 0),
    quarantineReason: row.querySelector('[name="quarantineReason"]')?.value || '',
  }));
  if (!lines.length || lines.some((line) => !line.productId || line.qty <= 0 || line.unitCost < 0 || line.quarantineQty < 0 || line.quarantineQty > line.qty || line.sellingPrice < 0 || (line.quarantineQty > 0 && !line.quarantineReason.trim()))) throw new Error('Complete every stock-in line with unit cost and selling price, then add a reason for quarantined units.');
  if (new Set(lines.map((line) => line.productId)).size !== lines.length) throw new Error('Add each product only once per stock-in receipt.');
  return lines;
}

function formatDateInput(date) {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function getDatePresetState(dateFrom, dateTo) {
  const now = new Date();
  const thisMonthStart = formatDateInput(new Date(now.getFullYear(), now.getMonth(), 1));
  const today = formatDateInput(now);
  const d30 = new Date();
  d30.setDate(d30.getDate() - 29);
  const last30Start = formatDateInput(d30);
  if (!dateFrom && !dateTo) return 'all';
  if (dateFrom === thisMonthStart && dateTo === today) return 'thisMonth';
  if (dateFrom === last30Start && dateTo === today) return 'last30';
  return '';
}

function renderDatePresets(activePreset, attrName = 'data-date-preset') {
  return `
    <div class="std-quick-dates">
      <span class="std-quick-dates-label">Presets:</span>
      <button type="button" class="std-date-btn ${activePreset === 'thisMonth' ? 'active' : ''}" ${attrName}="thisMonth">This Month</button>
      <button type="button" class="std-date-btn ${activePreset === 'last30' ? 'active' : ''}" ${attrName}="last30">Last 30 Days</button>
      <button type="button" class="std-date-btn ${activePreset === 'all' ? 'active' : ''}" ${attrName}="all">All Time</button>
    </div>
  `;
}

function handleDatePresetClick(preset, fromInputId, toInputId, onApply) {
  const dateFromEl = typeof fromInputId === 'string' ? $(`#${fromInputId}`) : fromInputId;
  const dateToEl = typeof toInputId === 'string' ? $(`#${toInputId}`) : toInputId;
  const today = new Date();
  if (preset === 'thisMonth') {
    if (dateFromEl) dateFromEl.value = formatDateInput(new Date(today.getFullYear(), today.getMonth(), 1));
    if (dateToEl) dateToEl.value = formatDateInput(today);
  } else if (preset === 'last30') {
    const past30 = new Date();
    past30.setDate(past30.getDate() - 29);
    if (dateFromEl) dateFromEl.value = formatDateInput(past30);
    if (dateToEl) dateToEl.value = formatDateInput(today);
  } else if (preset === 'all') {
    if (dateFromEl) dateFromEl.value = '';
    if (dateToEl) dateToEl.value = '';
  }
  if (dateFromEl) syncCustomDatePicker(dateFromEl);
  if (dateToEl) syncCustomDatePicker(dateToEl);
  if (typeof onApply === 'function') onApply();
}

function bindDatePresets(container, attrName, fromInputId, toInputId, onApply) {
  const root = typeof container === 'string' ? $(container) : container;
  if (!root || typeof root.querySelectorAll !== 'function') return;
  root.querySelectorAll(`[${attrName}]`).forEach((btn) => {
    btn.addEventListener('click', () => {
      const preset = btn.getAttribute(attrName);
      handleDatePresetClick(preset, fromInputId, toInputId, onApply);
    });
  });
}

if (typeof window !== 'undefined') {
  window.getDatePresetState = getDatePresetState;
  window.renderDatePresets = renderDatePresets;
  window.handleDatePresetClick = handleDatePresetClick;
  window.bindDatePresets = bindDatePresets;
}

